module.exports = "<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>IPTV CLIENTES - Painel de Controle</title>\n  <link rel=\"manifest\" href=\"/manifest.json\">\n  <meta name=\"theme-color\" content=\"#0d55bc\">\n  <script src=\"https://cdn.tailwindcss.com\"></script>\n  <script>\n    tailwind.config = {\n      theme: {\n        extend: {\n          colors: {\n            brand: {\n              blue: '#0d55bc',\n              darkblue: '#0a3a82',\n              hoverblue: '#0a469e',\n              gold: '#ffb703',\n              orange: '#f59e0b',\n              ice: '#f0f5fc'\n            }\n          }\n        }\n      }\n    }\n  </script>\n  <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap\" rel=\"stylesheet\">\n  <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\">\n  <link rel=\"stylesheet\" href=\"css/style.css\">\n</head>\n<body class=\"bg-[#f0f5fc] text-black font-sans min-h-screen flex flex-col antialiased text-base\">\n\n  <!-- TOP NAVBAR COM AS CORES OFICIAIS DA LOGO (ROYAL BLUE & GOLD) -->\n  <header class=\"bg-white border-b-4 border-[#0d55bc] sticky top-0 z-40 px-6 py-3.5 shadow-md\">\n    <div class=\"max-w-7xl mx-auto flex justify-between items-center\">\n      <!-- Logo & Company Name -->\n      <div class=\"flex items-center space-x-4\">\n        <div id=\"headerLogoBox\" class=\"min-w-[60px] max-w-[200px] h-14 p-1 rounded-2xl bg-white border-2 border-[#0d55bc] flex items-center justify-center text-[#0d55bc] font-black text-2xl shadow-sm overflow-hidden relative shrink-0\">\n          <i id=\"headerLogoIcon\" class=\"fa-solid fa-tv text-2xl text-[#0d55bc]\"></i>\n          <img id=\"headerLogoImg\" class=\"hidden max-h-12 w-auto object-contain p-0.5\" alt=\"Logo da Empresa\">\n        </div>\n        <div>\n          <h1 id=\"headerCompanyName\" class=\"font-black text-2xl tracking-tight text-black flex items-center gap-2 leading-tight\">\n            IPTV CLIENTES\n          </h1>\n        </div>\n      </div>\n\n      <!-- WhatsApp Connection Status Badge & Actions -->\n      <div class=\"flex items-center space-x-4\">\n        <div id=\"waStatusBadge\" class=\"flex items-center space-x-2.5 px-4 py-2 rounded-full bg-[#efe8dc] border border-[#e2d7c5] text-sm font-bold\">\n          <span class=\"w-3 h-3 rounded-full bg-yellow-500 animate-pulse\" id=\"waStatusDot\"></span>\n          <span id=\"waStatusText\" class=\"text-slate-800\">Conectando WhatsApp...</span>\n        </div>\n\n\n\n        <button onclick=\"openClientModal()\" class=\"hidden md:flex items-center space-x-2 bg-gradient-to-r from-brand-orange to-brand-orangeDark hover:from-brand-orangeDark hover:to-orange-700 text-white font-bold text-sm px-5 py-2.5 rounded-xl shadow-md transition transform hover:scale-105\">\n          <i class=\"fa-solid fa-plus\"></i>\n          <span>Novo Cliente</span>\n        </button>\n      </div>\n    </div>\n  </header>\n\n  <!-- MAIN WRAPPER -->\n  <div class=\"max-w-7xl mx-auto w-full flex-1 flex flex-col md:flex-row gap-6 p-4 md:p-6\">\n\n    <!-- SIDEBAR NAVIGATION -->\n    <aside class=\"w-full md:w-64 flex flex-row md:flex-col gap-2.5 overflow-x-auto pb-2 md:pb-0\">\n      <button onclick=\"switchTab('dashboard')\" id=\"tabBtn-dashboard\" class=\"nav-tab active flex items-center space-x-3 px-5 py-3.5 rounded-xl font-bold text-base transition\">\n        <i class=\"fa-solid fa-chart-pie w-6 text-xl\"></i>\n        <span>Dashboard</span>\n      </button>\n\n      <button onclick=\"switchTab('clients')\" id=\"tabBtn-clients\" class=\"nav-tab flex items-center space-x-3 px-5 py-3.5 rounded-xl font-bold text-base transition\">\n        <i class=\"fa-solid fa-users text-brand-orange w-6 text-xl\"></i>\n        <span>Clientes (CRM)</span>\n      </button>\n\n      <button onclick=\"switchTab('plans')\" id=\"tabBtn-plans\" class=\"nav-tab flex items-center space-x-3 px-5 py-3.5 rounded-xl font-bold text-base transition\">\n        <i class=\"fa-solid fa-tv text-sky-600 w-6 text-xl\"></i>\n        <span>Cards de Planos</span>\n      </button>\n\n      <button onclick=\"switchTab('apps_servers')\" id=\"tabBtn-apps_servers\" class=\"nav-tab flex items-center space-x-3 px-5 py-3.5 rounded-xl font-bold text-base transition\">\n        <i class=\"fa-solid fa-mobile-screen-button text-purple-600 w-6 text-xl\"></i>\n        <span>Apps & Servidores</span>\n      </button>\n\n      <button onclick=\"switchTab('whatsapp')\" id=\"tabBtn-whatsapp\" class=\"nav-tab flex items-center space-x-3 px-5 py-3.5 rounded-xl font-bold text-base transition\">\n        <i class=\"fa-brands fa-whatsapp text-emerald-600 w-6 text-xl\"></i>\n        <span>Conectar WhatsApp</span>\n      </button>\n\n      <button onclick=\"switchTab('ai_prompt')\" id=\"tabBtn-ai_prompt\" class=\"nav-tab flex items-center space-x-3 px-5 py-3.5 rounded-xl font-bold text-base transition\">\n        <i class=\"fa-solid fa-robot text-brand-blue w-6 text-xl\"></i>\n        <span>IA & Prompt</span>\n      </button>\n\n      <button onclick=\"switchTab('interactive_menu')\" id=\"tabBtn-interactive_menu\" class=\"nav-tab flex items-center space-x-3 px-5 py-3.5 rounded-xl font-bold text-base transition\">\n        <i class=\"fa-solid fa-list-check text-purple-600 w-6 text-xl\"></i>\n        <span>Menu Automático</span>\n      </button>\n\n      <button onclick=\"switchTab('receipts')\" id=\"tabBtn-receipts\" class=\"nav-tab flex items-center space-x-3 px-5 py-3.5 rounded-xl font-bold text-base transition\">\n        <i class=\"fa-solid fa-receipt text-amber-600 w-6 text-xl\"></i>\n        <span>Recibos & Disparos</span>\n      </button>\n\n      <button onclick=\"switchTab('settings')\" id=\"tabBtn-settings\" class=\"nav-tab flex items-center space-x-3 px-5 py-3.5 rounded-xl font-bold text-base transition\">\n        <i class=\"fa-solid fa-gear text-slate-600 w-6 text-xl\"></i>\n        <span>Configurações</span>\n      </button>\n    </aside>\n\n    <!-- CONTENT AREA -->\n    <main class=\"flex-1 min-w-0\">\n\n      <!-- 1. TAB: DASHBOARD -->\n      <section id=\"tab-dashboard\" class=\"tab-content block space-y-6\">\n\n\n        <!-- Stats Cards -->\n        <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-5\">\n          <div class=\"bg-white border border-[#e2d7c5] p-6 rounded-2xl shadow-sm relative overflow-hidden\">\n            <div class=\"flex items-center justify-between\">\n              <div>\n                <p class=\"text-sm font-bold text-slate-500 uppercase tracking-wider\">Total de Clientes</p>\n                <h3 id=\"statTotalClients\" class=\"text-3xl font-extrabold text-slate-900 mt-1\">0</h3>\n              </div>\n              <div class=\"w-12 h-12 rounded-xl bg-brand-blue/10 text-brand-blue flex items-center justify-center text-2xl font-bold\">\n                <i class=\"fa-solid fa-users\"></i>\n              </div>\n            </div>\n          </div>\n\n          <div class=\"bg-white border border-[#e2d7c5] p-6 rounded-2xl shadow-sm relative overflow-hidden\">\n            <div class=\"flex items-center justify-between\">\n              <div>\n                <p class=\"text-sm font-bold text-slate-500 uppercase tracking-wider\">Planos Ativos</p>\n                <h3 id=\"statActiveClients\" class=\"text-3xl font-extrabold text-emerald-600 mt-1\">0</h3>\n              </div>\n              <div class=\"w-12 h-12 rounded-xl bg-emerald-500/10 text-emerald-600 flex items-center justify-center text-2xl font-bold\">\n                <i class=\"fa-solid fa-circle-check\"></i>\n              </div>\n            </div>\n          </div>\n\n          <div class=\"bg-white border border-[#e2d7c5] p-6 rounded-2xl shadow-sm relative overflow-hidden\">\n            <div class=\"flex items-center justify-between\">\n              <div>\n                <p class=\"text-sm font-bold text-slate-500 uppercase tracking-wider\">Vencem em 3d</p>\n                <h3 id=\"statExpiringClients\" class=\"text-3xl font-extrabold text-brand-orange mt-1\">0</h3>\n              </div>\n              <div class=\"w-12 h-12 rounded-xl bg-brand-orange/10 text-brand-orange flex items-center justify-center text-2xl font-bold\">\n                <i class=\"fa-solid fa-clock\"></i>\n              </div>\n            </div>\n          </div>\n\n          <div class=\"bg-white border border-[#e2d7c5] p-6 rounded-2xl shadow-sm relative overflow-hidden\">\n            <div class=\"flex items-center justify-between\">\n              <div>\n                <p class=\"text-sm font-bold text-slate-500 uppercase tracking-wider\">Planos Atrasados</p>\n                <h3 id=\"statExpiredClients\" class=\"text-3xl font-extrabold text-red-600 mt-1\">0</h3>\n              </div>\n              <div class=\"w-12 h-12 rounded-xl bg-red-500/10 text-red-600 flex items-center justify-center text-2xl font-bold\">\n                <i class=\"fa-solid fa-circle-exclamation\"></i>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <!-- ALERTS SECTION: EXPIRING TOMORROW & EXPIRED CLIENTS -->\n        <div id=\"alertsContainer\" class=\"space-y-4\">\n          <!-- Alerta Urgente: Falta 1 Dia -->\n          <div id=\"alertOneDayBox\" class=\"hidden bg-amber-50 border-2 border-amber-400 p-5 rounded-2xl shadow-sm\">\n            <div class=\"flex items-center justify-between mb-3\">\n              <h3 class=\"text-base font-extrabold text-amber-900 flex items-center gap-2\">\n                <i class=\"fa-solid fa-triangle-exclamation text-amber-600 text-xl animate-bounce\"></i>\n                <span>ALERTA URGENTE: Clientes com Vencimento AMANHÃ (Falta 1 Dia!)</span>\n              </h3>\n              <span id=\"alertOneDayCount\" class=\"bg-amber-500 text-white font-extrabold text-xs px-3 py-1 rounded-full\">0 Clientes</span>\n            </div>\n            <div id=\"alertOneDayList\" class=\"space-y-2\">\n              <!-- Renderizado via JS -->\n            </div>\n          </div>\n\n          <!-- Alerta Crítico: Planos Atrasados / Vencidos -->\n          <div id=\"alertExpiredBox\" class=\"hidden bg-red-50 border-2 border-red-400 p-5 rounded-2xl shadow-sm\">\n            <div class=\"flex items-center justify-between mb-3\">\n              <h3 class=\"text-base font-extrabold text-red-900 flex items-center gap-2\">\n                <i class=\"fa-solid fa-circle-exclamation text-red-600 text-xl animate-pulse\"></i>\n                <span>ALERTA CRÍTICO: Clientes com Plano ATRASADO / VENCIDO!</span>\n              </h3>\n              <span id=\"alertExpiredCount\" class=\"bg-red-600 text-white font-extrabold text-xs px-3 py-1 rounded-full\">0 Clientes</span>\n            </div>\n            <div id=\"alertExpiredList\" class=\"space-y-2\">\n              <!-- Renderizado via JS -->\n            </div>\n          </div>\n        </div>\n\n        <!-- Connection Card & Quick Actions -->\n        <div class=\"grid grid-cols-1 lg:grid-cols-3 gap-6\">\n          <!-- WhatsApp Quick Status Card -->\n          <div class=\"bg-white border border-[#e2d7c5] rounded-2xl p-6 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-4\">\n                <h3 class=\"font-extrabold text-lg text-slate-900 flex items-center gap-2\">\n                  <i class=\"fa-brands fa-whatsapp text-emerald-600 text-2xl\"></i>\n                  <span>Robô de Vendas</span>\n                </h3>\n                <span class=\"text-xs bg-emerald-100 text-emerald-800 font-bold px-3 py-1 rounded-full\">Ativo 24h</span>\n              </div>\n              <p class=\"text-sm text-slate-600 mb-6\">O robô responde automaticamente seus clientes no WhatsApp com base nos dados do seu prompt e realiza renovações em 1 clique.</p>\n\n              <div id=\"dashWaStatusBox\" class=\"bg-[#f7f3ea] p-5 rounded-xl border border-[#e2d7c5] text-center\">\n                <i id=\"dashWaIcon\" class=\"fa-solid fa-circle-check text-4xl text-emerald-600 mb-2\"></i>\n                <p id=\"dashWaText\" class=\"font-bold text-slate-800 text-base\">WhatsApp Conectado</p>\n              </div>\n            </div>\n\n            <div class=\"mt-6 pt-4 border-t border-slate-200\">\n              <button onclick=\"switchTab('whatsapp')\" class=\"w-full bg-brand-blue hover:bg-sky-700 text-white font-bold py-3 rounded-xl text-sm transition flex items-center justify-center space-x-2\">\n                <i class=\"fa-solid fa-qrcode\"></i>\n                <span>Ver QR Code / Conectar</span>\n              </button>\n            </div>\n          </div>\n\n          <!-- Quick Actions & Cloud Hosting Guide -->\n          <div class=\"lg:col-span-2 bg-white border border-[#e2d7c5] rounded-2xl p-6 shadow-sm flex flex-col justify-between\">\n            <div>\n              <h3 class=\"font-extrabold text-lg text-slate-900 mb-3 flex items-center gap-2\">\n                <i class=\"fa-solid fa-cloud text-brand-blue text-xl\"></i>\n                <span>Hospedagem Grátis 24 Horas na Nuvem</span>\n              </h3>\n              <p class=\"text-sm text-slate-600 mb-4 leading-relaxed\">\n                Para manter este sistema rodando <b>24 horas por dia</b> mesmo com seu computador desligado, você pode hospedá-lo gratuitamente no <b>Render.com</b> ou <b>Koyeb</b> + <b>UptimeRobot</b>.\n              </p>\n\n              <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n                <div class=\"bg-[#f7f3ea] p-4 rounded-xl border border-[#e2d7c5]\">\n                  <span class=\"font-extrabold text-brand-orange text-base block mb-1\">1. Render.com / Koyeb (Grátis)</span>\n                  <p class=\"text-xs text-slate-600\">Suba o código deste projeto para o GitHub e conecte ao Render para rodar o Node.js 24/7.</p>\n                </div>\n                <div class=\"bg-[#f7f3ea] p-4 rounded-xl border border-[#e2d7c5]\">\n                  <span class=\"font-extrabold text-brand-blue text-base block mb-1\">2. UptimeRobot (Grátis)</span>\n                  <p class=\"text-xs text-slate-600\">Configure um monitor HTTP grátis pingando a URL <code>/ping</code> a cada 5 minutos para evitar hibernação.</p>\n                </div>\n              </div>\n            </div>\n\n            <div class=\"mt-6 pt-4 border-t border-slate-200 flex justify-end\">\n              <button onclick=\"openClientModal()\" class=\"bg-gradient-to-r from-brand-orange to-brand-orangeDark hover:from-brand-orangeDark hover:to-orange-700 text-white font-bold px-6 py-3 rounded-xl text-sm shadow-md transition transform hover:scale-105\">\n                <i class=\"fa-solid fa-user-plus\"></i>\n                <span>Cadastrar Novo Cliente</span>\n              </button>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- 2. TAB: CLIENTS (CRM) -->\n      <section id=\"tab-clients\" class=\"tab-content hidden space-y-6\">\n        <!-- Filter, Search and View Toggle Bar -->\n        <div class=\"bg-white border border-[#e2d7c5] p-5 rounded-2xl shadow-sm flex flex-col md:flex-row justify-between items-center gap-4\">\n          <div class=\"relative w-full md:w-80\">\n            <i class=\"fa-solid fa-magnifying-glass absolute left-3.5 top-3.5 text-slate-400 text-base\"></i>\n            <input type=\"text\" id=\"searchClientInput\" oninput=\"filterClients()\" placeholder=\"Buscar por código, nome, app ou servidor...\" class=\"w-full pl-10 pr-4 py-3 bg-white border border-slate-300 rounded-xl text-base text-slate-900 focus:outline-none focus:border-brand-blue\">\n          </div>\n\n          <div class=\"flex items-center space-x-3 w-full md:w-auto overflow-x-auto\">\n            <select id=\"filterStatusSelect\" onchange=\"filterClients()\" class=\"p-3 bg-white border border-slate-300 rounded-xl text-sm font-bold text-slate-800 focus:outline-none\">\n              <option value=\"all\">Todos os Status</option>\n              <option value=\"active\">🟢 Ativos</option>\n              <option value=\"expiring\">🟠 Próximos do Vencimento</option>\n              <option value=\"expired\">🔴 Vencidos</option>\n            </select>\n\n            <!-- Seletor de Modo de Visualização (Cards vs Tabela) -->\n            <div class=\"flex bg-[#efe8dc] p-1 rounded-xl border border-[#e2d7c5]\">\n              <button id=\"viewBtnCards\" onclick=\"setCrmViewMode('cards')\" class=\"px-4 py-2 rounded-lg text-sm font-bold transition bg-brand-blue text-white shadow-sm\">\n                <i class=\"fa-solid fa-id-card\"></i> Cards 🃏\n              </button>\n              <button id=\"viewBtnTable\" onclick=\"setCrmViewMode('table')\" class=\"px-4 py-2 rounded-lg text-sm font-bold text-slate-700 hover:text-slate-900 transition\">\n                <i class=\"fa-solid fa-table-list\"></i> Tabela 📊\n              </button>\n            </div>\n\n            <button onclick=\"openClientModal()\" class=\"bg-brand-orange hover:bg-orange-600 text-white text-sm px-5 py-3 rounded-xl font-bold transition flex items-center space-x-2 whitespace-nowrap shadow-sm\">\n              <i class=\"fa-solid fa-user-plus\"></i>\n              <span>Novo Cliente</span>\n            </button>\n          </div>\n        </div>\n\n        <!-- MODO CARDS (GRID DE 2 CARDS AMPLOS POR LINHA) -->\n        <div id=\"clientsCardsGrid\" class=\"grid grid-cols-1 lg:grid-cols-2 gap-6\">\n          <!-- Cards gerados via JS -->\n        </div>\n\n        <!-- MODO TABELA (VISUALIZAÇÃO EM LISTA) -->\n        <div id=\"clientsTableView\" class=\"hidden bg-white border border-[#e2d7c5] rounded-2xl overflow-hidden shadow-sm\">\n          <div class=\"overflow-x-auto\">\n            <table class=\"w-full text-left text-base text-slate-800\">\n              <thead class=\"bg-[#f0e9dd] text-sm uppercase text-slate-700 font-extrabold border-b border-[#e2d7c5]\">\n                <tr>\n                  <th class=\"py-4 px-4\">Código</th>\n                  <th class=\"py-4 px-4\">Cliente</th>\n                  <th class=\"py-4 px-4\">WhatsApp</th>\n                  <th class=\"py-4 px-4\">Plano & Valor</th>\n                  <th class=\"py-4 px-4\">App & Servidor</th>\n                  <th class=\"py-4 px-4\">Vencimento (30d)</th>\n                  <th class=\"py-4 px-4\">Status</th>\n                  <th class=\"py-4 px-4 text-right\">Ações</th>\n                </tr>\n              </thead>\n              <tbody id=\"clientsTableBody\" class=\"divide-y divide-[#e2d7c5]\">\n                <!-- Linhas inseridas via JS -->\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </section>\n\n      <!-- 2.1 TAB: CARDS DE PLANOS DE CANAIS COM CORES -->\n      <section id=\"tab-plans\" class=\"tab-content hidden space-y-6\">\n        <div class=\"bg-white border border-[#e2d7c5] rounded-2xl p-6 shadow-sm\">\n          <div class=\"flex items-center justify-between mb-6\">\n            <div class=\"flex items-center space-x-3\">\n              <div class=\"w-12 h-12 rounded-xl bg-sky-500/10 text-sky-600 flex items-center justify-center text-2xl font-bold\">\n                <i class=\"fa-solid fa-tv\"></i>\n              </div>\n              <div>\n                <h2 class=\"text-xl font-extrabold text-slate-900\">Cadastro de Cards de Planos de Canais</h2>\n                <p class=\"text-sm text-slate-600\">Cadastre os planos com cores personalizadas para cada card.</p>\n              </div>\n            </div>\n          </div>\n\n          <!-- Add Plan Form with Color Picker and Screens Count -->\n          <form id=\"addPlanForm\" onsubmit=\"saveNewPlan(event)\" class=\"bg-[#f0f5fc] p-5 rounded-3xl border-2 border-brand-blue/30 mb-6 space-y-4 shadow-sm\">\n            <h3 class=\"text-base font-black text-black flex items-center gap-2\">\n              <i class=\"fa-solid fa-palette text-brand-blue text-lg\"></i>\n              <span>Criar Novo Card de Plano Personalizado</span>\n            </h3>\n\n            <div class=\"grid grid-cols-1 md:grid-cols-5 gap-4\">\n              <div class=\"md:col-span-2\">\n                <label class=\"block text-xs font-black text-black mb-1\">Nome do Plano *</label>\n                <input type=\"text\" id=\"newPlanName\" required placeholder=\"Ex: Plano Mensal Premium\" class=\"w-full p-3 bg-white border border-slate-300 rounded-xl text-base text-black focus:outline-none font-bold\">\n              </div>\n\n              <div>\n                <label class=\"block text-xs font-black text-black mb-1\">Valor Mensal (R$) *</label>\n                <input type=\"number\" step=\"0.01\" id=\"newPlanPrice\" required placeholder=\"35.00\" class=\"w-full p-3 bg-white border border-slate-300 rounded-xl text-base text-black focus:outline-none font-extrabold\">\n              </div>\n\n              <div>\n                <label class=\"block text-xs font-black text-black mb-1\">Qtd. de Telas *</label>\n                <select id=\"newPlanScreens\" class=\"w-full p-3 bg-white border border-slate-300 rounded-xl text-base text-black font-extrabold focus:outline-none\">\n                  <option value=\"1 Tela\">📺 1 Tela</option>\n                  <option value=\"2 Telas\">📺 2 Telas</option>\n                  <option value=\"3 Telas\">📺 3 Telas</option>\n                  <option value=\"4 Telas\">📺 4 Telas</option>\n                  <option value=\"Telas Ilimitadas\">🚀 Telas Ilimitadas</option>\n                </select>\n              </div>\n\n              <div>\n                <label class=\"block text-xs font-black text-black mb-1\">Cor do Card *</label>\n                <select id=\"newPlanColor\" class=\"w-full p-3 bg-white border border-slate-300 rounded-xl text-base text-black font-extrabold focus:outline-none\">\n                  <option value=\"#0d55bc\">🟦 Royal Blue (Oficial GN)</option>\n                  <option value=\"#059669\">🟩 Verde Esmeralda</option>\n                  <option value=\"#d97706\">🟧 Amarelo Ouro</option>\n                  <option value=\"#7c3aed\">🟪 Roxo Imperial</option>\n                  <option value=\"#dc2626\">🟥 Vermelho Carmim</option>\n                  <option value=\"#0284c7\">🩵 Azul Celeste</option>\n                </select>\n              </div>\n            </div>\n\n            <div>\n              <label class=\"block text-xs font-black text-black mb-1\">Descrição do Plano / Conteúdo Incluso</label>\n              <input type=\"text\" id=\"newPlanDesc\" placeholder=\"Ex: Todos os canais HD/4K + Filmes e Séries 4K + Esportes ao Vivo\" class=\"w-full p-3 bg-white border border-slate-300 rounded-xl text-base text-black focus:outline-none font-bold\">\n            </div>\n\n            <div class=\"flex justify-end\">\n              <button type=\"submit\" class=\"bg-brand-blue hover:bg-blue-800 text-white font-black px-6 py-3 rounded-xl text-sm transition flex items-center space-x-2 shadow-sm active:scale-95\">\n                <i class=\"fa-solid fa-plus\"></i>\n                <span>Salvar Card de Plano</span>\n              </button>\n            </div>\n          </form>\n\n          <!-- Registered Colorful Plan Cards Grid -->\n          <h3 class=\"text-base font-extrabold text-slate-900 mb-4\">Cards de Planos Ativos no Sistema</h3>\n          <div id=\"plansGrid\" class=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6\">\n            <!-- Cards de planos gerados via JS -->\n          </div>\n        </div>\n      </section>\n\n      <!-- 2.2 TAB: APPS & SERVIDORES IPTV -->\n      <section id=\"tab-apps_servers\" class=\"tab-content hidden space-y-6\">\n        <div class=\"grid grid-cols-1 lg:grid-cols-2 gap-6\">\n          <!-- GERENCIADOR DE APLICATIVOS -->\n          <div class=\"bg-white border border-[#e2d7c5] rounded-2xl p-6 shadow-sm\">\n            <div class=\"flex items-center space-x-3 mb-6\">\n              <div class=\"w-12 h-12 rounded-xl bg-purple-500/10 text-purple-600 flex items-center justify-center text-2xl font-bold\">\n                <i class=\"fa-solid fa-mobile-screen-button\"></i>\n              </div>\n              <div>\n                <h2 class=\"text-xl font-extrabold text-slate-900\">Aplicativos IPTV</h2>\n                <p class=\"text-sm text-slate-600\">Cadastre os apps usados pelos seus clientes.</p>\n              </div>\n            </div>\n\n            <form id=\"addAppForm\" onsubmit=\"saveNewApp(event)\" class=\"bg-[#f7f3ea] p-4 rounded-xl border border-[#e2d7c5] mb-5 space-y-3\">\n              <div>\n                <label class=\"block text-xs font-bold text-slate-700 mb-1\">Nome do Aplicativo *</label>\n                <input type=\"text\" id=\"newAppName\" required placeholder=\"Ex: XCIPTV Player, IBO Player\" class=\"w-full p-3 bg-white border border-slate-300 rounded-xl text-base text-slate-900 font-medium\">\n              </div>\n              <div class=\"flex justify-end\">\n                <button type=\"submit\" class=\"bg-purple-600 hover:bg-purple-700 text-white font-bold px-5 py-2.5 rounded-xl text-sm transition shadow-sm\">\n                  <i class=\"fa-solid fa-plus\"></i> Cadastrar App\n                </button>\n              </div>\n            </form>\n\n            <div id=\"appsList\" class=\"space-y-2\">\n              <!-- Lista de Apps via JS -->\n            </div>\n          </div>\n\n          <!-- GERENCIADOR DE SERVIDORES -->\n          <div class=\"bg-white border border-[#e2d7c5] rounded-2xl p-6 shadow-sm\">\n            <div class=\"flex items-center space-x-3 mb-6\">\n              <div class=\"w-12 h-12 rounded-xl bg-brand-blue/10 text-brand-blue flex items-center justify-center text-2xl font-bold\">\n                <i class=\"fa-solid fa-server\"></i>\n              </div>\n              <div>\n                <h2 class=\"text-xl font-extrabold text-slate-900\">Servidores IPTV</h2>\n                <p class=\"text-sm text-slate-600\">Cadastre os servidores que sua empresa utiliza.</p>\n              </div>\n            </div>\n\n            <form id=\"addServerForm\" onsubmit=\"saveNewServer(event)\" class=\"bg-[#f7f3ea] p-4 rounded-xl border border-[#e2d7c5] mb-5 space-y-3\">\n              <div>\n                <label class=\"block text-xs font-bold text-slate-700 mb-1\">Nome do Servidor *</label>\n                <input type=\"text\" id=\"newServerName\" required placeholder=\"Ex: Servidor Premium Gold, Servidor Star\" class=\"w-full p-3 bg-white border border-slate-300 rounded-xl text-base text-slate-900 font-medium\">\n              </div>\n              <div class=\"flex justify-end\">\n                <button type=\"submit\" class=\"bg-brand-blue hover:bg-sky-700 text-white font-bold px-5 py-2.5 rounded-xl text-sm transition shadow-sm\">\n                  <i class=\"fa-solid fa-plus\"></i> Cadastrar Servidor\n                </button>\n              </div>\n            </form>\n\n            <div id=\"serversList\" class=\"space-y-2\">\n              <!-- Lista de Servidores via JS -->\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- 3. TAB: CONNECT WHATSAPP -->\n      <section id=\"tab-whatsapp\" class=\"tab-content hidden space-y-6\">\n        <div class=\"bg-white border border-[#e2d7c5] rounded-2xl p-8 text-center max-w-xl mx-auto shadow-sm\">\n          <div class=\"w-20 h-20 bg-emerald-500/10 text-emerald-600 rounded-full flex items-center justify-center text-4xl mx-auto mb-4 border border-emerald-500/20\">\n            <i class=\"fa-brands fa-whatsapp\"></i>\n          </div>\n\n          <h2 class=\"text-2xl font-extrabold text-slate-900 mb-2\">Conectar WhatsApp (Normal ou Business)</h2>\n          <p class=\"text-sm text-slate-600 mb-6\">Abra o WhatsApp no seu celular, vá em <b class=\"text-slate-800\">Aparelhos Conectados &rarr; Conectar um Aparelho</b> e aponte a câmera para o QR Code abaixo.</p>\n\n          <!-- QR Code View Box -->\n          <div id=\"qrCodeContainer\" class=\"bg-white p-5 rounded-2xl inline-block shadow-xl border-4 border-brand-blue min-w-[260px] min-h-[260px] flex items-center justify-center relative\">\n            <div id=\"qrLoadingSpinner\" class=\"flex flex-col items-center space-y-3 text-slate-700\">\n              <i class=\"fa-solid fa-circle-notch fa-spin text-5xl text-brand-blue\"></i>\n              <span class=\"text-sm font-bold\">Gerando QR Code...</span>\n            </div>\n            <img id=\"qrCodeImg\" class=\"hidden max-w-[240px] max-h-[240px] rounded-lg\" alt=\"QR Code WhatsApp\">\n          </div>\n\n          <!-- Status Message -->\n          <div id=\"waConnectStatusText\" class=\"mt-5 text-base font-bold text-slate-800\">\n            Aguardando escaneamento...\n          </div>\n\n          <div class=\"mt-6 flex justify-center space-x-3\">\n            <button onclick=\"reconnectWhatsApp()\" class=\"bg-brand-blue hover:bg-sky-700 text-white px-6 py-3 rounded-xl font-bold text-sm transition flex items-center space-x-2 shadow-sm\">\n              <i class=\"fa-solid fa-arrows-rotate\"></i>\n              <span>Gerar Novo QR Code</span>\n            </button>\n          </div>\n        </div>\n      </section>\n\n      <!-- 4. TAB: AI & PROMPT SETTINGS -->\n      <section id=\"tab-ai_prompt\" class=\"tab-content hidden space-y-6\">\n        <div class=\"bg-white border border-[#e2d7c5] rounded-2xl p-6 shadow-sm\">\n          <div class=\"flex items-center space-x-3 mb-6\">\n            <div class=\"w-12 h-12 rounded-xl bg-brand-blue/10 text-brand-blue flex items-center justify-center text-2xl font-bold\">\n              <i class=\"fa-solid fa-robot\"></i>\n            </div>\n            <div>\n              <h2 class=\"text-xl font-extrabold text-slate-900\">Inteligência Artificial & Prompt do Sistema</h2>\n              <p class=\"text-sm text-slate-600\">Configure as regras de atendimento para a IA responder seus clientes automaticamente.</p>\n            </div>\n          </div>\n\n          <form id=\"aiPromptForm\" onsubmit=\"saveAiSettings(event)\" class=\"space-y-6\">\n            <div>\n              <label class=\"block text-sm font-bold text-slate-800 mb-1.5\">Chave API Google Gemini (Gratuito - Opcional)</label>\n              <input type=\"password\" id=\"geminiApiKey\" placeholder=\"Cole sua API Key do Google AI Studio (ou deixe em branco para usar o motor grátis)\" class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-base focus:outline-none focus:border-brand-blue text-slate-900 font-medium\">\n              <p class=\"text-xs text-slate-500 mt-1\">Se não preencher, o sistema usará o Motor de Regras Inteligente totalmente gratuito sem limites.</p>\n            </div>\n\n            <div>\n              <label class=\"block text-sm font-bold text-slate-800 mb-1.5\">Prompt Personalizado Geral do Sistema (Instruções da sua Empresa)</label>\n              <textarea id=\"systemPromptText\" rows=\"10\" class=\"w-full p-4 bg-white border border-slate-300 rounded-xl text-base focus:outline-none focus:border-brand-blue text-slate-900 font-mono leading-relaxed\" placeholder=\"Escreva aqui as regras do robô...\"></textarea>\n              <p class=\"text-xs text-brand-blue font-bold mt-1\">✨ A IA e o sistema usam esse texto para responder dúvidas sobre preços, suporte, testes e regras dos canais.</p>\n            </div>\n\n            <!-- Caixa de Adição Rápida de Informações ao Prompt -->\n            <div class=\"bg-[#f7f3ea] p-5 rounded-xl border border-[#e2d7c5] space-y-3\">\n              <label class=\"block text-sm font-extrabold text-brand-orange uppercase tracking-wider flex items-center gap-2\">\n                <i class=\"fa-solid fa-plus-circle text-lg\"></i>\n                <span>Adicionar Nova Informação / Regra ao Prompt Geral</span>\n              </label>\n              <div class=\"flex flex-col sm:flex-row gap-3\">\n                <input type=\"text\" id=\"quickPromptInfoInput\" placeholder=\"Ex: Promoção de Setembro: Plano Anual por R$ 250 no Pix\" class=\"flex-1 p-3 bg-white border border-slate-300 rounded-xl text-base text-slate-900 focus:outline-none focus:border-brand-orange font-medium\">\n                <button type=\"button\" onclick=\"appendQuickInfoToPrompt()\" class=\"bg-gradient-to-r from-brand-orange to-brand-orangeDark hover:from-brand-orangeDark hover:to-orange-700 text-white font-bold px-6 py-3 rounded-xl text-sm whitespace-nowrap transition flex items-center space-x-2 shadow-sm\">\n                  <i class=\"fa-solid fa-plus\"></i>\n                  <span>Anexar ao Prompt</span>\n                </button>\n              </div>\n              <p class=\"text-xs text-slate-600\">Esta informação será anexada ao Prompt Geral do sistema imediatamente e salva no banco de dados.</p>\n            </div>\n\n            <div class=\"grid grid-cols-1 md:grid-cols-2 gap-5\">\n              <div>\n                <label class=\"block text-sm font-bold text-slate-800 mb-1.5\">Duração do Teste Grátis</label>\n                <input type=\"text\" id=\"testDuration\" placeholder=\"ex: 2 horas, 4 horas\" class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-base focus:outline-none focus:border-brand-blue text-slate-900 font-medium\">\n              </div>\n\n              <div>\n                <label class=\"block text-sm font-bold text-slate-800 mb-1.5\">Chave PIX para Renovação (Salva e Preserva Seus Dados)</label>\n                <input type=\"text\" id=\"pixKeyInput\" placeholder=\"Ex: 11985897774 ou Banco CELCOIN - Gerailton Neves - Pix 11985897774\" class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-base focus:outline-none focus:border-brand-blue text-slate-900 font-medium\">\n              </div>\n\n              <!-- UPLOAD DE LOGO DA EMPRESA -->\n              <div class=\"bg-[#f7f3ea] p-5 rounded-2xl border border-[#e2d7c5] space-y-4\">\n                <label class=\"block text-sm font-extrabold text-slate-800 flex items-center gap-2\">\n                  <i class=\"fa-solid fa-image text-brand-orange text-lg\"></i>\n                  <span>Logo da Empresa (Para Recibos Profissionais)</span>\n                </label>\n                \n                <div class=\"flex flex-col sm:flex-row items-center gap-4\">\n                  <!-- Preview Box -->\n                  <div id=\"logoPreviewBox\" class=\"min-w-[100px] max-w-[220px] h-24 p-1 rounded-2xl bg-white border-2 border-dashed border-slate-300 flex items-center justify-center overflow-hidden relative shadow-sm shrink-0\">\n                    <i id=\"logoPreviewIcon\" class=\"fa-solid fa-cloud-arrow-up text-3xl text-slate-400\"></i>\n                    <img id=\"logoPreviewImg\" class=\"hidden max-h-20 w-auto object-contain p-1\" alt=\"Logo da Empresa\">\n                  </div>\n\n                  <!-- Upload Controls -->\n                  <div class=\"flex-1 space-y-2 text-center sm:text-left\">\n                    <input type=\"file\" id=\"logoFileInput\" accept=\"image/*\" onchange=\"uploadLogoFile(event)\" class=\"hidden\">\n                    <input type=\"hidden\" id=\"companyLogoInput\">\n                    \n                    <div class=\"flex flex-wrap gap-2 justify-center sm:justify-start\">\n                      <button type=\"button\" onclick=\"document.getElementById('logoFileInput').click()\" class=\"bg-brand-blue hover:bg-sky-700 text-white font-bold px-4 py-2.5 rounded-xl text-sm transition flex items-center space-x-2 shadow-sm\">\n                        <i class=\"fa-solid fa-upload\"></i>\n                        <span>Fazer Upload da Foto da Logo</span>\n                      </button>\n                      <button type=\"button\" onclick=\"removeLogoFile()\" class=\"bg-red-100 hover:bg-red-200 text-red-700 font-bold px-3 py-2.5 rounded-xl text-sm transition flex items-center space-x-1 border border-red-300\">\n                        <i class=\"fa-solid fa-trash\"></i>\n                        <span>Remover</span>\n                      </button>\n                    </div>\n                    <p class=\"text-xs text-slate-600 font-medium\">Selecione uma foto da sua marca do computador ou celular (PNG, JPG, WEBP). Ela aparecerá estampada nos recibos!</p>\n                  </div>\n                </div>\n              </div>\n            </div>\n\n            <div class=\"pt-2 flex justify-end\">\n              <button type=\"submit\" class=\"bg-brand-orange hover:bg-orange-600 text-white font-bold px-7 py-3 rounded-xl text-base transition flex items-center space-x-2 shadow-sm\">\n                <i class=\"fa-solid fa-floppy-disk\"></i>\n                <span>Salvar Configurações de IA</span>\n              </button>\n            </div>\n          </form>\n        </div>\n      </section>\n\n      <!-- 5. TAB: INTERACTIVE MENU -->\n      <section id=\"tab-interactive_menu\" class=\"tab-content hidden space-y-6\">\n        <div class=\"bg-white border border-[#e2d7c5] rounded-2xl p-6 shadow-sm\">\n          <h2 class=\"text-xl font-extrabold text-slate-900 mb-2 flex items-center gap-2\">\n            <i class=\"fa-solid fa-list-check text-purple-600\"></i>\n            <span>Menu Interativo de Autoatendimento</span>\n          </h2>\n          <p class=\"text-sm text-slate-600 mb-6\">Este é o menu automático enviado aos clientes na primeira mensagem ou quando enviam \"Menu\".</p>\n\n          <div class=\"grid grid-cols-1 lg:grid-cols-2 gap-6\">\n            <!-- Menu Preview Box -->\n            <div class=\"bg-[#f7f3ea] p-5 rounded-2xl border border-[#e2d7c5]\">\n              <h3 class=\"text-sm font-extrabold text-slate-700 uppercase tracking-wider mb-3\">Pré-visualização da Mensagem no WhatsApp</h3>\n              <div id=\"menuPreviewBox\" class=\"bg-white p-5 rounded-xl border border-slate-300 text-slate-900 font-mono text-sm whitespace-pre-wrap leading-relaxed shadow-inner\">\n                <!-- Preview carregado via JS -->\n              </div>\n            </div>\n\n            <!-- Options Description -->\n            <div class=\"space-y-4 text-base\">\n              <div class=\"bg-[#f7f3ea] p-4 rounded-xl border border-[#e2d7c5]\">\n                <span class=\"font-bold text-slate-900 block mb-1\">1️⃣ Consultar Vencimento & Pix</span>\n                <p class=\"text-xs text-slate-600\">Retorna o plano, valor, data de vencimento e chave Pix cadastrada no sistema.</p>\n              </div>\n\n              <div class=\"bg-[#f7f3ea] p-4 rounded-xl border border-[#e2d7c5]\">\n                <span class=\"font-bold text-slate-900 block mb-1\">2️⃣ Solicitar Teste Grátis</span>\n                <p class=\"text-xs text-slate-600\">Envia a mensagem solicitando o modelo de aparelho para geração de acesso temporário.</p>\n              </div>\n\n              <div class=\"bg-[#f7f3ea] p-4 rounded-xl border border-[#e2d7c5]\">\n                <span class=\"font-bold text-slate-900 block mb-1\">3️⃣ Ver Planos e Preços</span>\n                <p class=\"text-xs text-slate-600\">Envia a tabela completa dos planos Mensal, Trimestral e Anual.</p>\n              </div>\n\n              <div class=\"bg-[#f7f3ea] p-4 rounded-xl border border-[#e2d7c5]\">\n                <span class=\"font-bold text-slate-900 block mb-1\">4️⃣ Tirar Dúvidas com Atendente (IA)</span>\n                <p class=\"text-xs text-slate-600\">Aciona a Inteligência Artificial para responder qualquer dúvida usando o Prompt do Sistema.</p>\n              </div>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- 6. TAB: RECEIPTS & BROADCAST -->\n      <section id=\"tab-receipts\" class=\"tab-content hidden space-y-6\">\n        <div class=\"bg-white border border-[#e2d7c5] rounded-2xl p-6 shadow-sm\">\n          <div class=\"flex items-center space-x-3 mb-6\">\n            <div class=\"w-12 h-12 rounded-xl bg-amber-500/10 text-amber-600 flex items-center justify-center text-2xl font-bold\">\n              <i class=\"fa-solid fa-receipt\"></i>\n            </div>\n            <div>\n              <h2 class=\"text-xl font-extrabold text-slate-900\">Gerador de Recibos & Disparo de Promoções</h2>\n              <p class=\"text-sm text-slate-600\">Histórico de renovações com código de recibo e envio de mensagens para clientes.</p>\n            </div>\n          </div>\n\n          <!-- Broadcast Message Box -->\n          <div class=\"bg-[#f7f3ea] p-5 rounded-2xl border border-[#e2d7c5] mb-6 space-y-4\">\n            <h3 class=\"text-base font-extrabold text-slate-900 flex items-center gap-2\">\n              <i class=\"fa-solid fa-paper-plane text-brand-orange\"></i>\n              <span>Enviar Mensagem de Promoção ou Aviso em Massa</span>\n            </h3>\n\n            <div>\n              <label class=\"block text-xs font-bold text-slate-700 mb-1\">Público Alvo</label>\n              <select id=\"broadcastTargetSelect\" class=\"w-full p-3 bg-white border border-slate-300 rounded-xl text-base font-medium text-slate-900 focus:outline-none\">\n                <option value=\"expiring\">🟠 Apenas Clientes Próximos do Vencimento (3 dias)</option>\n                <option value=\"expired\">🔴 Apenas Clientes com Plano Vencido</option>\n                <option value=\"all\">🟢 Todos os Clientes Cadastrados</option>\n              </select>\n            </div>\n\n            <div>\n              <label class=\"block text-xs font-bold text-slate-700 mb-1\">Mensagem da Promoção / Aviso</label>\n              <textarea id=\"broadcastMessageText\" rows=\"3\" class=\"w-full p-3 bg-white border border-slate-300 rounded-xl text-base text-slate-900 focus:outline-none\" placeholder=\"Digite a mensagem promocional ou lembrete...\"></textarea>\n            </div>\n\n            <div class=\"flex justify-end\">\n              <button onclick=\"sendBroadcastMessage()\" class=\"bg-brand-orange hover:bg-orange-600 text-white font-bold px-6 py-3 rounded-xl text-sm transition flex items-center space-x-2 shadow-sm\">\n                <i class=\"fa-solid fa-paper-plane\"></i>\n                <span>Enviar Notificação aos Clientes</span>\n              </button>\n            </div>\n          </div>\n\n          <!-- Receipts History Table -->\n          <div class=\"flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3 mb-3\">\n            <div>\n              <h3 class=\"text-base font-extrabold text-slate-900 flex items-center gap-2\">\n                <i class=\"fa-solid fa-clock-rotate-left text-amber-600 text-lg\"></i>\n                <span>Histórico de Recibos de Renovação</span>\n              </h3>\n              <p class=\"text-xs text-slate-600 font-medium\">Você tem acesso completo para <b>Ver</b>, <b>Editar</b>, <b>Excluir</b> ou <b>Reenviar no WhatsApp</b> cada recibo.</p>\n            </div>\n            <button onclick=\"loadReceipts()\" class=\"bg-amber-100 hover:bg-amber-200 text-amber-900 font-bold px-3.5 py-2 rounded-xl text-xs transition border border-amber-300 flex items-center space-x-1.5 shadow-sm whitespace-nowrap\">\n              <i class=\"fa-solid fa-arrows-rotate\"></i>\n              <span>Atualizar Recibos</span>\n            </button>\n          </div>\n\n          <div class=\"overflow-x-auto border border-[#e2d7c5] rounded-xl shadow-sm\">\n            <table class=\"w-full text-left text-base text-slate-800\">\n              <thead class=\"bg-[#f0e9dd] text-sm uppercase text-slate-700 font-extrabold\">\n                <tr>\n                  <th class=\"py-3.5 px-4\">Código Recibo</th>\n                  <th class=\"py-3.5 px-4\">Cliente</th>\n                  <th class=\"py-3.5 px-4\">Plano</th>\n                  <th class=\"py-3.5 px-4\">Valor</th>\n                  <th class=\"py-3.5 px-4\">Data Renovação</th>\n                  <th class=\"py-3.5 px-4\">Próximo Vencimento</th>\n                  <th class=\"py-3.5 px-4 text-right\">Ação</th>\n                </tr>\n              </thead>\n              <tbody id=\"receiptsTableBody\" class=\"divide-y divide-[#e2d7c5]\">\n                <!-- Recibos inseridos via JS -->\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </section>\n\n      <!-- 7. TAB: COMPANY SETTINGS -->\n      <section id=\"tab-settings\" class=\"tab-content hidden space-y-6\">\n        <div class=\"bg-white border border-[#e2d7c5] rounded-2xl p-6 shadow-sm\">\n          <div class=\"flex items-center space-x-3 mb-6\">\n            <div class=\"w-12 h-12 rounded-xl bg-slate-200 text-slate-700 flex items-center justify-center text-2xl font-bold\">\n              <i class=\"fa-solid fa-sliders\"></i>\n            </div>\n            <div>\n              <h2 class=\"text-xl font-extrabold text-slate-900\">Configurações Gerais da Empresa</h2>\n              <p class=\"text-sm text-slate-600\">Personalize o nome da sua empresa e chave PIX exibidos no sistema.</p>\n            </div>\n          </div>\n\n          <form id=\"companySettingsForm\" onsubmit=\"saveCompanySettings(event)\" class=\"space-y-5\">\n            <div>\n              <label class=\"block text-sm font-bold text-slate-800 mb-1.5\">Nome da Sua Empresa</label>\n              <input type=\"text\" id=\"companyNameInput\" placeholder=\"Ex: IPTV CLIENTES Brasil\" class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-base focus:outline-none focus:border-brand-blue text-slate-900 font-medium\">\n              <p class=\"text-xs text-slate-500 mt-1\">Este nome será exibido nas saudações e no recibo gerado aos clientes.</p>\n            </div>\n\n            <div>\n              <label class=\"block text-sm font-bold text-slate-800 mb-1.5\">Ativar Robô de Resposta Automática</label>\n              <select id=\"botEnabledSelect\" class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-base font-medium text-slate-900 focus:outline-none\">\n                <option value=\"true\">🟢 Sim - Ativado (Robô responde automático no WhatsApp 24h)</option>\n                <option value=\"false\">🔴 Não - Desativado (Apenas gestão manual de clientes)</option>\n              </select>\n            </div>\n\n            <div class=\"pt-2 flex justify-end\">\n              <button type=\"submit\" class=\"bg-brand-blue hover:bg-sky-700 text-white font-bold px-7 py-3 rounded-xl text-base transition flex items-center space-x-2 shadow-sm\">\n                <i class=\"fa-solid fa-floppy-disk\"></i>\n                <span>Salvar Dados da Empresa</span>\n              </button>\n            </div>\n          </form>\n        </div>\n      </section>\n\n    </main>\n  </div>\n\n  <!-- MODAL: CADASTRAR / EDITAR CLIENTE -->\n  <div id=\"clientModal\" class=\"fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 hidden flex items-center justify-center p-4\">\n    <div class=\"bg-white border border-[#e2d7c5] rounded-3xl max-w-lg w-full p-7 shadow-2xl animate-fade-in relative max-h-[90vh] overflow-y-auto\">\n      <div class=\"flex justify-between items-center mb-6\">\n        <h3 id=\"clientModalTitle\" class=\"text-xl font-extrabold text-slate-900\">Cadastrar Novo Cliente</h3>\n        <button onclick=\"closeClientModal()\" class=\"text-slate-400 hover:text-slate-700 text-2xl font-bold\">&times;</button>\n      </div>\n\n      <form id=\"clientForm\" onsubmit=\"saveClient(event)\" class=\"space-y-4\">\n        <input type=\"hidden\" id=\"clientId\">\n\n        <div>\n          <label class=\"block text-sm font-bold text-slate-800 mb-1\">Nome Completo do Cliente *</label>\n          <input type=\"text\" id=\"clientName\" required placeholder=\"Ex: João da Silva\" class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-base text-slate-900 focus:outline-none focus:border-brand-blue font-medium\">\n        </div>\n\n        <div>\n          <label class=\"block text-sm font-bold text-slate-800 mb-1\">Número do WhatsApp * (DDD + Número)</label>\n          <input type=\"text\" id=\"clientPhone\" required placeholder=\"Ex: 11985897774 (Sem colocar o 55 na frente)\" class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-base text-slate-900 focus:outline-none focus:border-brand-blue font-medium\">\n        </div>\n\n        <div>\n          <label class=\"block text-sm font-bold text-slate-800 mb-1\">Selecione o Plano de Canais</label>\n          <select id=\"clientPlanSelect\" onchange=\"onClientPlanSelectChange()\" class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-base text-slate-900 font-bold focus:outline-none\">\n            <!-- Opções inseridas via JS -->\n          </select>\n        </div>\n\n        <div class=\"grid grid-cols-2 gap-3\">\n          <div>\n            <label class=\"block text-sm font-bold text-slate-800 mb-1\">Nome do Plano</label>\n            <input type=\"text\" id=\"clientPlanName\" placeholder=\"Ex: IPTV CLIENTES 1 Tela\" class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-base text-slate-900 focus:outline-none font-medium\">\n          </div>\n\n          <div>\n            <label class=\"block text-sm font-bold text-slate-800 mb-1\">Valor Mensal (R$)</label>\n            <input type=\"number\" step=\"0.01\" id=\"clientPrice\" placeholder=\"35.00\" class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-base text-slate-900 focus:outline-none font-bold\">\n          </div>\n        </div>\n\n        <div class=\"grid grid-cols-2 gap-3\">\n          <div>\n            <label class=\"block text-sm font-bold text-slate-800 mb-1\">📱 Aplicativo Usado</label>\n            <select id=\"clientAppSelect\" class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-base text-slate-900 font-medium focus:outline-none\">\n              <!-- Opções de Apps via JS -->\n            </select>\n          </div>\n\n          <div>\n            <label class=\"block text-sm font-bold text-slate-800 mb-1\">🖥 Servidor Usado</label>\n            <select id=\"clientServerSelect\" class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-base text-slate-900 font-medium focus:outline-none\">\n              <!-- Opções de Servidores via JS -->\n            </select>\n          </div>\n        </div>\n\n        <div class=\"grid grid-cols-2 gap-3\">\n          <div>\n            <label class=\"block text-sm font-bold text-slate-800 mb-1\">Vencimento *</label>\n            <input type=\"date\" id=\"clientDueDate\" required class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-base text-slate-900 focus:outline-none font-medium\">\n          </div>\n\n          <div>\n            <label class=\"block text-sm font-bold text-slate-800 mb-1\">Status do Plano</label>\n            <select id=\"clientStatus\" class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-base text-slate-900 font-bold focus:outline-none\">\n              <option value=\"active\">🟢 Ativo</option>\n              <option value=\"expiring\">🟠 Próx. Vencimento</option>\n              <option value=\"expired\">🔴 Vencido / Suspenso</option>\n            </select>\n          </div>\n        </div>\n\n        <div>\n          <label class=\"block text-sm font-bold text-slate-800 mb-1\">Observações / Código Personalizado</label>\n          <input type=\"text\" id=\"clientNotes\" placeholder=\"Ex: CÓDIGO PROMPT: #812600\" class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-base text-slate-900 focus:outline-none font-medium\">\n        </div>\n\n        <div class=\"pt-4 flex justify-end space-x-3\">\n          <button type=\"button\" onclick=\"closeClientModal()\" class=\"px-5 py-3 rounded-xl border border-slate-300 text-slate-700 font-bold text-sm hover:bg-slate-100 transition\">Cancelar</button>\n          <button type=\"submit\" class=\"bg-brand-orange hover:bg-orange-600 text-white font-bold px-6 py-3 rounded-xl text-sm transition shadow-sm\">Salvar Cliente</button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <!-- MODAL: RECIBO DE RENOVAÇÃO PROFISSIONAL -->\n  <div id=\"receiptModal\" style=\"display: none;\" class=\"fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4\">\n    <div class=\"bg-white border border-[#e2d7c5] rounded-3xl max-w-lg w-full p-6 shadow-2xl animate-fade-in relative space-y-4 max-h-[90vh] overflow-y-auto\">\n      <div class=\"flex justify-between items-center pb-3 border-b border-slate-200\">\n        <h3 class=\"text-xl font-extrabold text-slate-900 flex items-center gap-2\">\n          <i class=\"fa-solid fa-receipt text-amber-600 text-2xl\"></i>\n          <span>Recibo de Renovação</span>\n        </h3>\n        <button onclick=\"closeReceiptModal()\" class=\"text-slate-400 hover:text-slate-700 text-2xl font-bold\">&times;</button>\n      </div>\n\n      <!-- VISUAL RECEIPT CARD (PROFISSIONAL COM LOGO) -->\n      <div id=\"receiptVisualCard\" class=\"bg-gradient-to-b from-slate-900 to-slate-800 text-white rounded-2xl p-6 shadow-lg border border-slate-700 relative overflow-hidden\">\n        <!-- Logo & Header -->\n        <div class=\"flex items-center justify-between border-b border-slate-700 pb-4 mb-4\">\n          <div class=\"flex items-center space-x-3\">\n            <div id=\"receiptLogoBox\" class=\"w-12 h-12 rounded-xl bg-white/10 flex items-center justify-center overflow-hidden border border-white/20\">\n              <i class=\"fa-solid fa-tv text-amber-400 text-2xl\"></i>\n            </div>\n            <div>\n              <h4 id=\"receiptCompanyName\" class=\"font-extrabold text-lg tracking-wide text-white\">GN IPTV</h4>\n              <span class=\"text-xs text-amber-400 font-bold uppercase tracking-wider\">Comprovante Oficial de Renovação</span>\n            </div>\n          </div>\n          <span id=\"receiptCodeBadge\" class=\"bg-amber-500/20 text-amber-300 border border-amber-500/40 font-mono font-extrabold text-xs px-3 py-1.5 rounded-lg shadow-sm\">\n            REC-000000\n          </span>\n        </div>\n\n        <!-- Details Grid -->\n        <div class=\"space-y-3 text-sm\">\n          <div class=\"flex justify-between border-b border-slate-700/60 pb-2\">\n            <span class=\"text-slate-400\">Cliente:</span>\n            <span id=\"receiptClientNameText\" class=\"font-bold text-white\">Nome do Cliente</span>\n          </div>\n\n          <div class=\"flex justify-between border-b border-slate-700/60 pb-2\">\n            <span class=\"text-slate-400\">Plano Contratado:</span>\n            <span id=\"receiptPlanNameText\" class=\"font-bold text-amber-300\">IPTV CLIENTES 1 Tela</span>\n          </div>\n\n          <div class=\"flex justify-between border-b border-slate-700/60 pb-2\">\n            <span class=\"text-slate-400\">Valor Pago:</span>\n            <span id=\"receiptPriceText\" class=\"font-extrabold text-emerald-400 text-base\">R$ 35,00</span>\n          </div>\n\n          <div class=\"flex justify-between border-b border-slate-700/60 pb-2\">\n            <span class=\"text-slate-400\">Data do Pagamento:</span>\n            <span id=\"receiptDateText\" class=\"font-bold text-slate-200\">DD/MM/AAAA</span>\n          </div>\n\n          <div class=\"flex justify-between bg-emerald-500/10 p-3 rounded-xl border border-emerald-500/30\">\n            <span class=\"text-emerald-300 font-bold flex items-center gap-1.5\">\n              <i class=\"fa-solid fa-calendar-check\"></i> Próximo Vencimento:\n            </span>\n            <span id=\"receiptNextDueText\" class=\"font-extrabold text-emerald-300 text-base\">DD/MM/AAAA</span>\n          </div>\n        </div>\n\n        <div class=\"mt-4 pt-3 border-t border-slate-700/60 text-center text-xs text-slate-400 italic\">\n          Obrigado pela preferência! Desejamos um ótimo entretenimento! 🍿📺\n        </div>\n      </div>\n\n      <!-- TEXT AREA FORMAT (PARA WHATSAPP) -->\n      <div class=\"bg-[#f7f3ea] p-3.5 rounded-xl border border-[#e2d7c5]\">\n        <label class=\"block text-xs font-bold text-slate-700 mb-1\">Texto Formatado para WhatsApp:</label>\n        <div id=\"receiptBoxContent\" class=\"bg-white p-3 rounded-xl border border-slate-300 font-mono text-xs text-slate-900 whitespace-pre-wrap leading-relaxed max-h-36 overflow-y-auto\">\n          <!-- Conteúdo do recibo em texto gerado via JS -->\n        </div>\n      </div>\n\n      <!-- ACTION BUTTONS -->\n      <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 pt-1\">\n        <button onclick=\"copyReceiptText()\" class=\"bg-slate-800 hover:bg-slate-900 text-white font-bold py-2.5 px-3 rounded-xl text-xs transition flex items-center justify-center space-x-1.5 shadow-sm\">\n          <i class=\"fa-solid fa-copy\"></i>\n          <span>Copiar</span>\n        </button>\n        <button onclick=\"sendReceiptViaWhatsapp()\" class=\"bg-emerald-600 hover:bg-emerald-700 text-white font-bold py-2.5 px-3 rounded-xl text-xs transition flex items-center justify-center space-x-1.5 shadow-sm\">\n          <i class=\"fa-brands fa-whatsapp\"></i>\n          <span>WhatsApp</span>\n        </button>\n        <button onclick=\"printVisualReceipt()\" class=\"bg-brand-blue hover:bg-sky-700 text-white font-bold py-2.5 px-3 rounded-xl text-xs transition flex items-center justify-center space-x-1.5 shadow-sm\">\n          <i class=\"fa-solid fa-print\"></i>\n          <span>Imprimir</span>\n        </button>\n        <button onclick=\"deleteCurrentActiveReceipt()\" class=\"bg-red-600 hover:bg-red-700 text-white font-bold py-2.5 px-3 rounded-xl text-xs transition flex items-center justify-center space-x-1.5 shadow-sm\">\n          <i class=\"fa-solid fa-trash\"></i>\n          <span>Excluir</span>\n        </button>\n      </div>\n    </div>\n  </div>\n\n  <!-- MODAL: EDITAR RECIBO -->\n  <div id=\"editReceiptModal\" style=\"display: none;\" class=\"fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4\">\n    <div class=\"bg-white border border-[#e2d7c5] rounded-3xl max-w-md w-full p-6 shadow-2xl animate-fade-in relative space-y-4\">\n      <div class=\"flex justify-between items-center pb-2 border-b border-slate-200\">\n        <h3 class=\"text-lg font-extrabold text-slate-900 flex items-center gap-2\">\n          <i class=\"fa-solid fa-pen-to-square text-brand-orange\"></i>\n          <span>Editar Dados do Recibo</span>\n        </h3>\n        <button onclick=\"closeEditReceiptModal()\" class=\"text-slate-400 hover:text-slate-700 text-2xl font-bold\">&times;</button>\n      </div>\n\n      <form id=\"editReceiptForm\" onsubmit=\"saveEditedReceipt(event)\" class=\"space-y-3.5\">\n        <input type=\"hidden\" id=\"editReceiptId\">\n\n        <div>\n          <label class=\"block text-xs font-bold text-slate-700 mb-1\">Código do Recibo *</label>\n          <input type=\"text\" id=\"editReceiptCode\" required class=\"w-full p-3 bg-white border border-slate-300 rounded-xl text-sm font-mono font-bold text-slate-900\">\n        </div>\n\n        <div>\n          <label class=\"block text-xs font-bold text-slate-700 mb-1\">Nome do Cliente *</label>\n          <input type=\"text\" id=\"editReceiptClientName\" required class=\"w-full p-3 bg-white border border-slate-300 rounded-xl text-sm font-bold text-slate-900\">\n        </div>\n\n        <div>\n          <label class=\"block text-xs font-bold text-slate-700 mb-1\">Plano Renovado *</label>\n          <input type=\"text\" id=\"editReceiptPlanName\" required class=\"w-full p-3 bg-white border border-slate-300 rounded-xl text-sm font-bold text-slate-900\">\n        </div>\n\n        <div class=\"grid grid-cols-2 gap-3\">\n          <div>\n            <label class=\"block text-xs font-bold text-slate-700 mb-1\">Valor Pago (R$) *</label>\n            <input type=\"number\" step=\"0.01\" id=\"editReceiptPrice\" required class=\"w-full p-3 bg-white border border-slate-300 rounded-xl text-sm font-bold text-slate-900\">\n          </div>\n\n          <div>\n            <label class=\"block text-xs font-bold text-slate-700 mb-1\">Data Pagamento *</label>\n            <input type=\"text\" id=\"editReceiptRenewedAt\" required class=\"w-full p-3 bg-white border border-slate-300 rounded-xl text-sm font-bold text-slate-900\">\n          </div>\n        </div>\n\n        <div>\n          <label class=\"block text-xs font-bold text-slate-700 mb-1\">Próximo Vencimento (AAAA-MM-DD) *</label>\n          <input type=\"date\" id=\"editReceiptNextDue\" required class=\"w-full p-3 bg-white border border-slate-300 rounded-xl text-sm font-bold text-slate-900\">\n        </div>\n\n        <div class=\"pt-2 flex justify-end space-x-2\">\n          <button type=\"button\" onclick=\"closeEditReceiptModal()\" class=\"bg-slate-200 hover:bg-slate-300 text-slate-700 font-bold px-4 py-2.5 rounded-xl text-xs\">Cancelar</button>\n          <button type=\"submit\" class=\"bg-brand-orange hover:bg-orange-600 text-white font-bold px-5 py-2.5 rounded-xl text-xs shadow-sm\">Salvar Alterações</button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <!-- MODAL: ENVIAR MENSAGEM RÁPIDA WHATSAPP -->\n  <div id=\"quickMessageModal\" class=\"fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 hidden flex items-center justify-center p-4\">\n    <div class=\"bg-white border border-[#e2d7c5] rounded-3xl max-w-lg w-full p-7 shadow-2xl animate-fade-in relative\">\n      <div class=\"flex justify-between items-center mb-4\">\n        <h3 class=\"text-xl font-extrabold text-slate-900 flex items-center gap-2\">\n          <i class=\"fa-brands fa-whatsapp text-emerald-600 text-2xl\"></i>\n          <span>Enviar Mensagem de Aviso</span>\n        </h3>\n        <button onclick=\"closeQuickMessageModal()\" class=\"text-slate-400 hover:text-slate-700 text-2xl font-bold\">&times;</button>\n      </div>\n\n      <div class=\"space-y-4\">\n        <div class=\"bg-[#f7f3ea] p-4 rounded-xl border border-[#e2d7c5]\">\n          <p class=\"text-xs font-bold text-slate-500 uppercase\">Cliente Selecionado</p>\n          <p id=\"qmClientName\" class=\"font-extrabold text-slate-900 text-base\">Nome do Cliente</p>\n          <p id=\"qmClientPhone\" class=\"text-xs font-mono text-slate-600\">5511999999999</p>\n        </div>\n\n        <div>\n          <label class=\"block text-sm font-bold text-slate-800 mb-1\">Selecione o Modelo de Aviso</label>\n          <select id=\"qmTemplateSelect\" onchange=\"updateQuickMessagePreview()\" class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-base font-bold text-slate-900 focus:outline-none\">\n            <option value=\"today\">🗓 Aviso: Vence HOJE</option>\n            <option value=\"tomorrow\">⏳ Aviso: Vence AMANHÃ (Falta 1 Dia)</option>\n            <option value=\"expired\">🔴 Aviso: Plano ATRASADO / VENCIDO</option>\n            <option value=\"renewed\">🎉 Aviso: Plano RENOVADO (Com Recibo)</option>\n            <option value=\"referral1\">🎁 Promoção: Indique 1 Amigo/Parente (1 Mês Grátis!)</option>\n            <option value=\"referral2\">🔥 Promoção: Indique 2 Amigos/Parentes (2 Meses Grátis!)</option>\n          </select>\n        </div>\n\n        <div>\n          <label class=\"block text-sm font-bold text-slate-800 mb-1\">Mensagem a ser enviada</label>\n          <textarea id=\"qmMessageText\" rows=\"6\" class=\"w-full p-3.5 bg-white border border-slate-300 rounded-xl text-sm font-mono text-slate-900 focus:outline-none leading-relaxed\"></textarea>\n        </div>\n\n        <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-3 pt-2\">\n          <button onclick=\"sendQuickMessageSocket()\" class=\"bg-emerald-600 hover:bg-emerald-700 text-white font-bold py-3 px-4 rounded-xl text-sm transition flex items-center justify-center space-x-2 shadow-sm\">\n            <i class=\"fa-solid fa-robot\"></i>\n            <span>Enviar via Robô</span>\n          </button>\n          <button onclick=\"openQuickMessageWhatsAppWeb()\" class=\"bg-brand-blue hover:bg-sky-700 text-white font-bold py-3 px-4 rounded-xl text-sm transition flex items-center justify-center space-x-2 shadow-sm\">\n            <i class=\"fa-brands fa-whatsapp\"></i>\n            <span>Abrir no WhatsApp</span>\n          </button>\n        </div>\n      </div>\n  <!-- BARRA DE NAVEGAÇÃO INFERIOR PARA CELULARES (MOBILE BOTTOM NAV BAR) -->\n  <div class=\"mobile-bottom-nav md:hidden\">\n    <button onclick=\"switchTab('dashboard')\" id=\"mobTab-dashboard\" class=\"mobile-bottom-btn active\">\n      <i class=\"fa-solid fa-chart-pie\"></i>\n      <span>Dashboard</span>\n    </button>\n    <button onclick=\"switchTab('clients')\" id=\"mobTab-clients\" class=\"mobile-bottom-btn\">\n      <i class=\"fa-solid fa-users\"></i>\n      <span>Clientes</span>\n    </button>\n    <button onclick=\"openClientModal()\" class=\"mobile-bottom-btn bg-brand-orange text-white px-3.5 py-3 rounded-full shadow-lg transform -translate-y-3 border-2 border-white\">\n      <i class=\"fa-solid fa-plus text-xl mb-0\"></i>\n    </button>\n    <button onclick=\"switchTab('receipts')\" id=\"mobTab-receipts\" class=\"mobile-bottom-btn\">\n      <i class=\"fa-solid fa-receipt\"></i>\n      <span>Recibos</span>\n    </button>\n    <button onclick=\"switchTab('whatsapp')\" id=\"mobTab-whatsapp\" class=\"mobile-bottom-btn\">\n      <i class=\"fa-brands fa-whatsapp\"></i>\n      <span>Robô IA</span>\n    </button>\n  </div>\n\n  <script src=\"js/app.js\"></script>\n</body>\n</html>";